import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static int[] parent, size;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path halving
            x = parent[x];
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), q = nextInt();
        parent = new int[n + 1];
        size = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int i = 0; i < m; i++) {
            int a = find(nextInt()), b = find(nextInt());
            if (a != b) {
                if (size[a] < size[b]) { // union by size
                    int t = a;
                    a = b;
                    b = t;
                }
                parent[b] = a;
                size[a] += size[b];
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            if (k > 0) sb.append(' ');
            sb.append(size[find(nextInt())]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

var parent, size []int

func find(x int) int {
	for parent[x] != x {
		parent[x] = parent[parent[x]] // path halving
		x = parent[x]
	}
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, q := int(nextInt()), int(nextInt()), int(nextInt())
	parent = make([]int, n+1)
	size = make([]int, n+1)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	for i := 0; i < m; i++ {
		a, b := find(int(nextInt())), find(int(nextInt()))
		if a != b {
			if size[a] < size[b] { // union by size
				a, b = b, a
			}
			parent[b] = a
			size[a] += size[b]
		}
	}
	var out []byte
	for k := 0; k < q; k++ {
		if k > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(size[find(int(nextInt()))]), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
